INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.PF', 'IN', '2026-v2', '2026-09-17', NULL, '{"kind":"pf","wageCeiling":"25000","employeeRate":"0.12","employerRate":"0.12","epsRate":"0.0833","epsCeiling":"25000","epsStopAge":58,"edliRate":"0.005","edliCeiling":"15000","adminRate":"0.005","adminMinimum":"500","rounding":"nearest"}', 'PF wage ceiling raised from 15,000 to 25,000 a month, notified 17 Sep 2026 (S.O. 5109(E), Code on Social Security 2020); EPS employer maximum 2,083 a month (PIB PRID 2310973, 2313829). The EDLI and admin-charge ceilings were not found and stay as before (TODO: CA checklist item 46 confirms them). Rates as the 2025 version.', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP);
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'From 17 Sep 2026: basic 20,000 is below the 25,000 ceiling: employee 2,400, EPS 1,666, EPF 734', 'pf', '{"pfWage":"20000","onActualWage":false,"age":30}', '{"employee":"2400","eps":"1666","epf":"734","edli":"75"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.PF' AND "jurisdiction" = 'IN' AND "version" = '2026-v2';
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'From 17 Sep 2026: basic 30,000 on the 25,000 ceiling: employee 3,000, EPS 2,083, EPF 917', 'pf', '{"pfWage":"30000","onActualWage":false,"age":30}', '{"employee":"3000","eps":"2083","epf":"917","edli":"75"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.PF' AND "jurisdiction" = 'IN' AND "version" = '2026-v2';
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'Age 58: no EPS, the whole employer share goes to EPF', 'pf', '{"pfWage":"25000","onActualWage":false,"age":58}', '{"employee":"3000","eps":"0","epf":"3000","edli":"75"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.PF' AND "jurisdiction" = 'IN' AND "version" = '2026-v2';
INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.PT', 'IN-TN', '2026-v2', '2026-10-01', NULL, '{"kind":"pt","basis":"half_yearly","deductMonths":[8,1],"annualCap":"2500","slabs":[{"from":"0","to":"21000","amount":"0"},{"from":"21000.01","to":"30000","amount":"180"},{"from":"30000.01","to":"45000","amount":"425"},{"from":"45000.01","to":"60000","amount":"930"},{"from":"60000.01","to":"75000","amount":"1025"},{"from":"75000.01","to":null,"amount":"1250"}]}', 'Greater Chennai Corporation, professional tax press release R.D. PT C.No/3555/2026 dated 04.08.2026 (TN Urban Local Bodies Rules 2023 r.277(2)-(3)): deducted from the August and January pay bills; slabs unchanged (rates II/2024-25). Other Tamil Nadu local bodies are not modelled. In force from the half-year starting 1 Oct 2026 (the April-September 2026 half-year was already deducted in September).', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP);
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'Half-year income 1,80,000 in January: 1,250', 'pt', '{"ptWage":"180000","month":1}', '{"amount":"1250"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.PT' AND "jurisdiction" = 'IN-TN' AND "version" = '2026-v2';
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'Half-year income 40,000 in August: 425', 'pt', '{"ptWage":"40000","month":8}', '{"amount":"425"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.PT' AND "jurisdiction" = 'IN-TN' AND "version" = '2026-v2';
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'September and March are no longer deduction months', 'pt', '{"ptWage":"180000","month":9}', '{"amount":"0"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.PT' AND "jurisdiction" = 'IN-TN' AND "version" = '2026-v2';
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'March: nothing', 'pt', '{"ptWage":"180000","month":3}', '{"amount":"0"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.PT' AND "jurisdiction" = 'IN-TN' AND "version" = '2026-v2';
INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.CALENDAR', 'IN-TN', 'TN-2026-v2', '2026-10-01', NULL, '{"kind":"calendar","items":[{"key":"pt","label":"Professional tax (Tamil Nadu)","dueDay":30,"monthOffset":1},{"key":"lwf","label":"Labour welfare fund (Tamil Nadu)","dueDay":31,"monthOffset":1}]}', 'Greater Chennai Corporation press release R.D. PT C.No/3555/2026 dated 04.08.2026 (TN Urban Local Bodies Rules 2023 r.277(3)): the August deduction is remitted by 30 September with Form 14. The January remittance date is not stated (TODO: CA checklist item 4); the same rule (the end of the next month) is used until the CA confirms it. Tamil Nadu Labour Welfare Fund Act, 1972 s.15 (yearly contribution paid by 31 January).', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP);
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'August half-year PT is due 30 September', 'calendar', '{"key":"pt","month":"2026-08"}', '{"due":"2026-09-30"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.CALENDAR' AND "jurisdiction" = 'IN-TN' AND "version" = 'TN-2026-v2';
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'January half-year PT: the end of February until the CA confirms (item 4)', 'calendar', '{"key":"pt","month":"2027-01"}', '{"due":"2027-02-28"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.CALENDAR' AND "jurisdiction" = 'IN-TN' AND "version" = 'TN-2026-v2';
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'December LWF is due 31 January', 'calendar', '{"key":"lwf","month":"2026-12"}', '{"due":"2027-01-31"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.CALENDAR' AND "jurisdiction" = 'IN-TN' AND "version" = 'TN-2026-v2';
